import {MODULE_ID} from '../../framework/constants.js';

/**
 * Blade Ward (PHB'24) — while the ward is up, every attack roll made against the
 * warded creature (the caster) takes a −1d4 penalty for the concentration
 * duration.
 *
 * HOW IT WORKS: on cast, a marker active effect flagged
 * flags[MODULE_ID].bladeWard is placed on the caster (a self-write — the caster
 * owns their own actor) and linked to the spell's concentration effect so it
 * ends when concentration does. Because the marker is module-flagged, any later
 * attack roll that targets the warded creature routes to this automation by
 * EFFECT SCOPE, even when the ward's owner is offline. On the attacker's own
 * client, `attackRollConfigure` pushes '-1d4' into the attack roll's parts when
 * a targeted defender carries the ward (visible in the roll formula).
 * The vanilla cast and the attack roll are never blocked or cancelled.
 *
 * The PHB'14 version of Blade Ward is a declarative resistance active effect and
 * is intentionally left to vanilla — this automation keys off its own marker
 * effect, so it is inert on the '14 version.
 */

/** Build the marker effect placed on the caster while the ward is up. */
function buildWardEffect(item) {
    return {
        name: item.name,
        img: item.img,
        description: 'Attack rolls made against you take a −1d4 penalty while this ward is up.',
        flags: {
            [MODULE_ID]: {
                // Effect-scope marker: routes attackers' rolls against this actor
                // back to the bladeWard automation.
                bladeWard: true
            }
        }
    };
}

// Only the acting client runs this (spellCastComplete fires on the caster, who
// owns their own actor — placing the ward effect is a plain owned write).
async function cast(context) {
    const actor = context.actor;
    if (!actor) return;

    // Link the marker to concentration so it is removed with the spell.
    const concentration = context.results?.effects
        ?.find(effect => effect.statuses?.has?.(CONFIG.specialStatusEffects.CONCENTRATING)) ?? null;

    let placed = false;
    if (concentration) {
        // Fold the marker into the concentration effect so it lives and dies with it.
        // Concentration effects are owned by the caster: a plain owned write.
        try {
            await concentration.setFlag(MODULE_ID, 'bladeWard', true);
            placed = true;
        } catch (error) {
            console.error(`${MODULE_ID} | Blade Ward: could not flag concentration effect`, error);
        }
    }

    if (!placed) {
        // No concentration effect to piggyback on (e.g. cast without concentration):
        // create a standalone marker on the caster instead.
        try {
            await actor.createEmbeddedDocuments('ActiveEffect', [buildWardEffect(context.item)]);
            placed = true;
        } catch (error) {
            console.error(`${MODULE_ID} | Blade Ward: could not place ward effect`, error);
        }
    }

    // If !placed, both attempts already logged to console; the cast stays vanilla.
}

/**
 * Runs synchronously on the ATTACKER's client, before the attack roll is
 * evaluated. The event reached this automation by effect scope because a targeted
 * defender carries the bladeWard marker. Push a −1d4 penalty into the roll for
 * each such target (once, regardless of how many warded targets there are — the
 * spell wards a single creature and multi-target attacks are the exception).
 * Never cancels the roll.
 */
function applyPenalty(context) {
    const targets = context.targets ?? [];
    const warded = targets.filter(target => carriesWard(target.actor));
    if (!warded.length) return;

    const roll = context.config?.rolls?.[0];
    if (!roll) return; // Roll structure unparseable — leave the vanilla roll untouched.
    roll.parts ??= [];
    roll.parts.push('-1d4');
}

/** Does this actor carry an active Blade Ward marker effect? */
function carriesWard(actor) {
    if (!actor) return false;
    const effects = actor.appliedEffects ?? actor.effects ?? [];
    return effects.some(effect => effect.flags?.[MODULE_ID]?.bladeWard);
}

export const bladeWard = {
    id: 'bladeWard',
    name: 'Blade Ward',
    description: 'On cast, marks the caster with a Blade Ward effect (linked to concentration). Every attack roll made against the warded creature automatically takes −1d4 (visible in the roll formula), applied on the attacker\'s own client via effect-scope routing — so it works even when the ward\'s owner is offline. The PHB\'14 resistance version is left to vanilla.',
    version: '1.2.0',
    autogenerated: true,
    match: {
        itemNames: ['Blade Ward']
    },
    events: [
        // Item-lifecycle: without the scope, the ward marker on the caster routed
        // every spell they cast back here via effect scope — each unrelated cast
        // re-ran cast() and re-flagged its concentration / stacked ward markers.
        {
            event: 'spellCastComplete',
            handler: cast,
            priority: 50,
            scopes: ['item']
        },
        // Marker-driven: routed by the bladeWard flag on a targeted defender.
        {
            event: 'attackRollConfigure',
            handler: applyPenalty,
            priority: 50,
            scopes: ['effect']
        }
    ]
};
